-- Tags: long
-- long: many statements; over the time limit of the flaky check under the thread fuzzer.

-- Nested typed shared data and arrays of JSON: a SHARED JSON path with its own SHARED paths, dynamic paths and dynamic
-- shared data inside a chunk, a shared Dynamic with several types, Array(JSON(SHARED ...)) with empty arrays and
-- granules without rows, two array levels, sizeN subcolumns. Each line prints the equality flags of the Wide, Compact
-- with marks and Compact without marks tables against a Memory table of the type without SHARED, and a sample value.

SELECT '-- a SHARED JSON path with dynamic paths of mixed types';
DROP TABLE IF EXISTS nj_w; DROP TABLE IF EXISTS nj_cm; DROP TABLE IF EXISTS nj_cn; DROP TABLE IF EXISTS nj_mem;
CREATE TABLE nj_w (x UInt64, json JSON(SHARED j JSON)) ENGINE = MergeTree ORDER BY x SETTINGS min_bytes_for_wide_part = 0, min_rows_for_wide_part = 0, index_granularity = 4, min_compress_block_size = 1, map_serialization_version = 'basic', map_serialization_version_for_zero_level_parts = 'basic';
CREATE TABLE nj_cm (x UInt64, json JSON(SHARED j JSON)) ENGINE = MergeTree ORDER BY x SETTINGS min_bytes_for_wide_part = 1000000000, min_rows_for_wide_part = 1000000000, index_granularity = 4, write_marks_for_substreams_in_compact_parts = 1, map_serialization_version = 'basic', map_serialization_version_for_zero_level_parts = 'basic';
CREATE TABLE nj_cn (x UInt64, json JSON(SHARED j JSON)) ENGINE = MergeTree ORDER BY x SETTINGS min_bytes_for_wide_part = 1000000000, min_rows_for_wide_part = 1000000000, index_granularity = 4, write_marks_for_substreams_in_compact_parts = 0, map_serialization_version = 'basic', map_serialization_version_for_zero_level_parts = 'basic';
CREATE TABLE nj_mem (x UInt64, json JSON(j JSON)) ENGINE = Memory;
INSERT INTO nj_w SELECT number, concat('{"j":{"k":', if(number % 3 = 0, toString(number), concat('"s', toString(number), '"')), ',"l":', toString(number), '}}') FROM numbers(20);
INSERT INTO nj_cm SELECT number, concat('{"j":{"k":', if(number % 3 = 0, toString(number), concat('"s', toString(number), '"')), ',"l":', toString(number), '}}') FROM numbers(20);
INSERT INTO nj_cn SELECT number, concat('{"j":{"k":', if(number % 3 = 0, toString(number), concat('"s', toString(number), '"')), ',"l":', toString(number), '}}') FROM numbers(20);
