SELECT '-- a shared Dynamic with several types and a nested dynamic shared data inside the chunk';
DROP TABLE IF EXISTS nd_w; DROP TABLE IF EXISTS nd_cm; DROP TABLE IF EXISTS nd_cn; DROP TABLE IF EXISTS nd_mem;
CREATE TABLE nd_w (x UInt64, json JSON(SHARED d Dynamic(max_types = 1), SHARED j JSON(max_dynamic_paths = 1))) ENGINE = MergeTree ORDER BY x SETTINGS min_bytes_for_wide_part = 0, min_rows_for_wide_part = 0, index_granularity = 4, min_compress_block_size = 1, map_serialization_version = 'basic', map_serialization_version_for_zero_level_parts = 'basic';
CREATE TABLE nd_cm (x UInt64, json JSON(SHARED d Dynamic(max_types = 1), SHARED j JSON(max_dynamic_paths = 1))) ENGINE = MergeTree ORDER BY x SETTINGS min_bytes_for_wide_part = 1000000000, min_rows_for_wide_part = 1000000000, index_granularity = 4, write_marks_for_substreams_in_compact_parts = 1, map_serialization_version = 'basic', map_serialization_version_for_zero_level_parts = 'basic';
CREATE TABLE nd_cn (x UInt64, json JSON(SHARED d Dynamic(max_types = 1), SHARED j JSON(max_dynamic_paths = 1))) ENGINE = MergeTree ORDER BY x SETTINGS min_bytes_for_wide_part = 1000000000, min_rows_for_wide_part = 1000000000, index_granularity = 4, write_marks_for_substreams_in_compact_parts = 0, map_serialization_version = 'basic', map_serialization_version_for_zero_level_parts = 'basic';
CREATE TABLE nd_mem (x UInt64, json JSON(d Dynamic(max_types = 1), j JSON(max_dynamic_paths = 1))) ENGINE = Memory;
INSERT INTO nd_w SELECT number, concat('{"d":', multiIf(number % 3 = 0, toString(number), number % 3 = 1, concat('"d', toString(number), '"'), concat('[', toString(number), ']')), ',"j":{"k":', toString(number), ',"p":{"a":', toString(number * 2), ',"b":"b', toString(number % 3), '"}}}') FROM numbers(20);
INSERT INTO nd_cm SELECT number, concat('{"d":', multiIf(number % 3 = 0, toString(number), number % 3 = 1, concat('"d', toString(number), '"'), concat('[', toString(number), ']')), ',"j":{"k":', toString(number), ',"p":{"a":', toString(number * 2), ',"b":"b', toString(number % 3), '"}}}') FROM numbers(20);
INSERT INTO nd_cn SELECT number, concat('{"d":', multiIf(number % 3 = 0, toString(number), number % 3 = 1, concat('"d', toString(number), '"'), concat('[', toString(number), ']')), ',"j":{"k":', toString(number), ',"p":{"a":', toString(number * 2), ',"b":"b', toString(number % 3), '"}}}') FROM numbers(20);
