DROP TABLE IF EXISTS arr_w; CREATE TABLE arr_w (x UInt64, arr Array(JSON(SHARED a UInt64, SHARED b String))) ENGINE = MergeTree ORDER BY x SETTINGS min_bytes_for_wide_part = 0, min_rows_for_wide_part = 0, index_granularity = 4, min_compress_block_size = 1, map_serialization_version = 'basic', map_serialization_version_for_zero_level_parts = 'basic';
