DROP TABLE IF EXISTS arr_cm; CREATE TABLE arr_cm (x UInt64, arr Array(JSON(SHARED a UInt64, SHARED b String))) ENGINE = MergeTree ORDER BY x SETTINGS min_bytes_for_wide_part = 1000000000, min_rows_for_wide_part = 1000000000, index_granularity = 4, write_marks_for_substreams_in_compact_parts = 1, map_serialization_version = 'basic', map_serialization_version_for_zero_level_parts = 'basic';
