SELECT '-- two array levels and the sizeN subcolumns of a shared Array(Array(Nullable(Int64))) inside Array(JSON)';
DROP TABLE IF EXISTS aa_w; DROP TABLE IF EXISTS aa_cm; DROP TABLE IF EXISTS aa_cn; DROP TABLE IF EXISTS aa_mem;
CREATE TABLE aa_w (x UInt64, aa Array(Array(JSON(SHARED c Array(UInt8)))), az Array(JSON(SHARED zz Array(Array(Nullable(Int64))))), json JSON(SHARED items Array(JSON(SHARED big String, SHARED small String)))) ENGINE = MergeTree ORDER BY x SETTINGS min_bytes_for_wide_part = 0, min_rows_for_wide_part = 0, index_granularity = 4, min_compress_block_size = 1, map_serialization_version = 'basic', map_serialization_version_for_zero_level_parts = 'basic';
CREATE TABLE aa_cm (x UInt64, aa Array(Array(JSON(SHARED c Array(UInt8)))), az Array(JSON(SHARED zz Array(Array(Nullable(Int64))))), json JSON(SHARED items Array(JSON(SHARED big String, SHARED small String)))) ENGINE = MergeTree ORDER BY x SETTINGS min_bytes_for_wide_part = 1000000000, min_rows_for_wide_part = 1000000000, index_granularity = 4, write_marks_for_substreams_in_compact_parts = 1, map_serialization_version = 'basic', map_serialization_version_for_zero_level_parts = 'basic';
CREATE TABLE aa_cn (x UInt64, aa Array(Array(JSON(SHARED c Array(UInt8)))), az Array(JSON(SHARED zz Array(Array(Nullable(Int64))))), json JSON(SHARED items Array(JSON(SHARED big String, SHARED small String)))) ENGINE = MergeTree ORDER BY x SETTINGS min_bytes_for_wide_part = 1000000000, min_rows_for_wide_part = 1000000000, index_granularity = 4, write_marks_for_substreams_in_compact_parts = 0, map_serialization_version = 'basic', map_serialization_version_for_zero_level_parts = 'basic';
CREATE TABLE aa_mem (x UInt64, aa Array(Array(JSON(c Array(UInt8)))), az Array(JSON(zz Array(Array(Nullable(Int64))))), json JSON(items Array(JSON(big String, small String)))) ENGINE = Memory;
INSERT INTO aa_w SELECT number, [arrayMap(i -> CAST(concat('{"c":', toString(range(i)), '}'), 'JSON(SHARED c Array(UInt8))'), range(number % 3))], arrayMap(i -> CAST(concat('{"b":', toString(i), ',"zz":[[', toString(number), ',null],[', toString(i), ']]}'), 'JSON(SHARED zz Array(Array(Nullable(Int64))))'), range(number % 3)), concat('{"items":[', arrayStringConcat(arrayMap(i -> concat('{"big":"', repeat('b', 20 + i), '","small":"', toString(i), '"}'), range(number % 4)), ','), ']}') FROM numbers(20);
INSERT INTO aa_cm SELECT number, [arrayMap(i -> CAST(concat('{"c":', toString(range(i)), '}'), 'JSON(SHARED c Array(UInt8))'), range(number % 3))], arrayMap(i -> CAST(concat('{"b":', toString(i), ',"zz":[[', toString(number), ',null],[', toString(i), ']]}'), 'JSON(SHARED zz Array(Array(Nullable(Int64))))'), range(number % 3)), concat('{"items":[', arrayStringConcat(arrayMap(i -> concat('{"big":"', repeat('b', 20 + i), '","small":"', toString(i), '"}'), range(number % 4)), ','), ']}') FROM numbers(20);
INSERT INTO aa_cn SELECT number, [arrayMap(i -> CAST(concat('{"c":', toString(range(i)), '}'), 'JSON(SHARED c Array(UInt8))'), range(number % 3))], arrayMap(i -> CAST(concat('{"b":', toString(i), ',"zz":[[', toString(number), ',null],[', toString(i), ']]}'), 'JSON(SHARED zz Array(Array(Nullable(Int64))))'), range(number % 3)), concat('{"items":[', arrayStringConcat(arrayMap(i -> concat('{"big":"', repeat('b', 20 + i), '","small":"', toString(i), '"}'), range(number % 4)), ','), ']}') FROM numbers(20);
INSERT INTO aa_mem SELECT number, [arrayMap(i -> CAST(concat('{"c":', toString(range(i)), '}'), 'JSON(c Array(UInt8))'), range(number % 3))], arrayMap(i -> CAST(concat('{"b":', toString(i), ',"zz":[[', toString(number), ',null],[', toString(i), ']]}'), 'JSON(zz Array(Array(Nullable(Int64))))'), range(number % 3)), concat('{"items":[', arrayStringConcat(arrayMap(i -> concat('{"big":"', repeat('b', 20 + i), '","small":"', toString(i), '"}'), range(number % 4)), ','), ']}') FROM numbers(20);
SELECT 'aa [aa]', (SELECT arraySort(groupArray((x, toString(aa)))) FROM aa_w  SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString(aa)))) FROM aa_mem ), (SELECT arraySort(groupArray((x, toString(aa)))) FROM aa_cm  SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString(aa)))) FROM aa_mem ), (SELECT arraySort(groupArray((x, toString(aa)))) FROM aa_cn  SETTINGS max_threads = 1) = (SELECT arraySort(groupArray((x, toString(aa)))) FROM aa_mem ), (SELECT toString(aa) FROM aa_w WHERE x = 10);
